}

capitulo-6/potencia.md.code:
public static double potencia(int a, int n) {
    if (n == 0)
        return 1;
    int absExponente = Math.abs(n);
    double mitad = potencia(a, absExponente / 2);
    if (absExponente % 2 == 0)
        mitad = mitad * mitad;
    else
        mitad = mitad * mitad * a;
    return n < 0 ? 1.0 / mitad : mitad;
}

