    while (a <= b) {
        int m1 = a + (b - a) / 3;
        int m2 = b - (int) Math.ceil((b - a) / 3.0);
        if (arr[m1] == x || arr[m2] == x)
            return true;
        if (x < arr[m1])
            b = m1 - 1; // Buscar en el primer tercio
        else if (x > arr[m2])
            a = m2 + 1; // Buscar en el último tercio
        else {
            a = m1 + 1; // Buscar en el tercio central
            b = m2 - 1;
        }
    }
    // Elemento no encontrado
