public static void ordenar(int[] arr) {
    int a = 0, b = arr.length - 1;
    while (a < b) {
        int min = a, max = a;
        for (int j = a; j <= b; j++) {
            if (arr[j] < arr[min])
                min = j;
            if (arr[j] > arr[max])
                max = j;
        }
        // Intercambia el mínimo con el extremo izquierdo
        int temp = arr[a];
        arr[a] = arr[min];
        arr[min] = temp;
        if (max == a)
            max = min;
        // Intercambia el máximo con el extremo derecho
        temp = arr[b];
        arr[b] = arr[max];
        arr[max] = temp;
        a++;
        b--;
    }
}

